"let activeCanvas = null;

// Load CanvasRenderer class in sandbox
function loadCanvasRenderer() {
    const filePath = path.join(__dirname, '../../crates/flightreader-server/assets/js/canvas_renderer.js');
    const code = fs.readFileSync(filePath, 'utf-8');

    const windowObj = {
        addEventListener: () => {},
        devicePixelRatio: 1
    };

    const sandbox = {
        window: windowObj,
        global: windowObj,
        globalThis: windowObj,
        document: {
            getElementById: (id) => activeCanvas ? activeCanvas.canvas : null
        },
        Math,
        Infinity,
        NaN,
        parseInt,
        parseFloat,
        console
    };

    const script = new vm.Script(code);
    const context = vm.createContext(sandbox);
    script.runInContext(context);

    return windowObj.CanvasRenderer || sandbox.CanvasRenderer;
}

const CanvasRenderer = loadCanvasRenderer();

function instantiateRenderer() {
    activeCanvas = createMockCanvas();
    const renderer = new CanvasRenderer('trajectory-canvas');
    renderer.width = 800;
    renderer.height = 600;
    return { renderer, mock: activeCanvas };
}"

